// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address sender, uint128 amount) public {
        vm.assume(sender != address(0));

        vm.deal(sender, uint256(amount));

        uint256 beforeCount = c.depositsCount();

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: uint256(amount)}("");
        uint256 afterCount = c.depositsCount();

        assertTrue(afterCount == beforeCount + 1);
    }
}
